#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SortDecl {
    pub name: String,
    /// An inductive sort is freely generated by its constructor signatures.
    pub inductive: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SignatureKind {
    Constructor,
    Function,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Signature {
    pub name: String,
    pub arguments: Vec<String>,
    pub result: String,
    pub kind: SignatureKind,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum JudgmentKind {
    Relation,
    Transition,
    Evaluation,
    Typing,
    Denotation,
    Hoare,
    Equality,
    Satisfaction,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct JudgmentDecl {
    pub name: String,
    pub arguments: Vec<String>,
    pub kind: JudgmentKind,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RecordDecl {
    pub name: String,
    pub constructor: String,
    pub fields: Vec<(String, String)>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MonadDecl {
    pub name: String,
    pub bind: String,
    pub unit: String,
}

/// Templates contain indexed holes `$0`, `$1`, ... and literal punctuation.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct NotationDecl {
    pub judgment: String,
    pub unicode: String,
    pub ascii: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum DomainExpr {
    Flat(Vec<crate::Term>),
    Product(String, String),
    Function(String, String),
    Lifted(String),
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DomainDecl {
    pub name: String,
    pub expression: DomainExpr,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SemanticMap {
    pub name: String,
    pub input: String,
    pub output: String,
    pub entries: Vec<(crate::Term, crate::Term)>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct InductionCase {
    pub constructor: String,
    pub arguments: Vec<String>,
    pub steps: Vec<crate::ProofStep>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct InductionProof {
    pub name: String,
    pub variable: String,
    pub sort: String,
    pub lhs: crate::Term,
    pub rhs: crate::Term,
    pub cases: Vec<InductionCase>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ComputedBinding {
    /// Run before this zero-based relational premise; len means trailing.
    pub before_premise: usize,
    pub pattern: crate::Term,
    pub value: crate::Term,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ClauseDetail {
    pub clause: String,
    pub premise_labels: Vec<Option<String>>,
    pub bindings: Vec<ComputedBinding>,
    pub conditions: Vec<crate::Term>,
}

use crate::{Substitution, Term};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Rule {
    pub name: String,
    pub lhs: Term,
    pub rhs: Term,
    /// A condition must reduce to `true` before the rule applies.
    pub condition: Option<Term>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Equation {
    pub name: String,
    pub lhs: Term,
    pub rhs: Term,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ProofStep {
    pub axiom: String,
    pub reverse: bool,
    pub path: Vec<usize>,
    pub substitution: Substitution,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Proof {
    pub name: String,
    pub lhs: Term,
    pub rhs: Term,
    pub steps: Vec<ProofStep>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Clause {
    pub name: String,
    pub conclusion: Term,
    pub premises: Vec<Term>,
}

#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Module {
    pub name: String,
    /// Unresolved source imports. The module loader clears these after linking.
    pub imports: Vec<String>,
    pub rules: Vec<Rule>,
    pub equations: Vec<Equation>,
    pub proofs: Vec<Proof>,
    pub evaluations: Vec<Term>,
    pub clauses: Vec<Clause>,
    pub queries: Vec<Term>,
    pub sorts: Vec<SortDecl>,
    pub signatures: Vec<Signature>,
    pub judgments: Vec<JudgmentDecl>,
    pub notations: Vec<NotationDecl>,
    pub records: Vec<RecordDecl>,
    pub monads: Vec<MonadDecl>,
    pub domains: Vec<DomainDecl>,
    pub semantic_maps: Vec<SemanticMap>,
    pub fixed_points: Vec<String>,
    pub inductions: Vec<InductionProof>,
    pub clause_details: Vec<ClauseDetail>,
}
